import { assertTablesEmptyBeforeDrop } from 'ccms-shared';

// CC045 (spec 9.3; I-03, C-09): proof of payment on a transaction. One row per uploaded cashier receipt photo.
//
//   status       PENDING  the row is reserved and the object is being written to private storage (never served)
//                ACTIVE   stored and confirmed (the audit RECEIPT_UPLOADED is written with this change)
//                DELETED  removed by staff; the payment details are cleared, only ids and times remain
//   storage_key  generated by the server (receipts/<uuid>/<uuid>), never from the file name; never leaves Operations
//   or_number    the official receipt number as typed (text: leading zeros are kept)
//   amount       numeric(12,2): the money convention of CCCMS (exact decimal in PostgreSQL, a "1234.50" string in JSON)
//   receipt_date the date printed on the receipt (a calendar date)
//   storage_purged_at  when the object was deleted from storage (cleanup retries DELETED/stale PENDING rows without it)
// At most one PENDING or ACTIVE receipt per transaction. Keep identical to the TransactionReceipt entity and
// receiptRules() in src/lib/after-sync.js.
export const RECEIPT_MAX_BYTES = 2 * 1024 * 1024;

export const RECEIPTS_CHECK = [
  "status IN ('PENDING', 'ACTIVE', 'DELETED')",
  "content_type IN ('image/jpeg', 'image/png')",
  `size_bytes BETWEEN 1 AND ${RECEIPT_MAX_BYTES}`,
  "(status = 'DELETED' OR (or_number IS NOT NULL AND amount IS NOT NULL AND receipt_date IS NOT NULL))",
  "(or_number IS NULL OR or_number ~ '^[A-Za-z0-9][A-Za-z0-9-]{0,29}$')",
  '(amount IS NULL OR amount > 0)',
  "((status = 'DELETED') = (deleted_at IS NOT NULL))",
  "(status <> 'ACTIVE' OR confirmed_at IS NOT NULL)",
].join(' AND ');

export const RECEIPT_CONSTRAINTS = [
  ['transaction_receipts_transaction_fk', 'FOREIGN KEY (transaction_id) REFERENCES transactions (transaction_id)'],
  ['transaction_receipts_storage_key_uq', 'UNIQUE (storage_key)'],
  ['transaction_receipts_values_ck', `CHECK (${RECEIPTS_CHECK})`],
];
export const RECEIPT_INDEXES = [
  "CREATE UNIQUE INDEX IF NOT EXISTS transaction_receipts_one_live_uq ON transaction_receipts (transaction_id) WHERE status IN ('PENDING', 'ACTIVE')",
  "CREATE INDEX IF NOT EXISTS transaction_receipts_cleanup_idx ON transaction_receipts (created_at) WHERE storage_purged_at IS NULL AND status IN ('PENDING', 'DELETED')",
];

const TABLE_SQL = `
  CREATE TABLE transaction_receipts (
    attachment_id uuid NOT NULL,
    transaction_id uuid NOT NULL,
    office_id uuid NOT NULL,
    status character varying(10) NOT NULL DEFAULT 'PENDING',
    storage_key character varying(200) NOT NULL,
    content_type character varying(20) NOT NULL,
    size_bytes integer NOT NULL,
    sha256 character varying(64) NOT NULL,
    or_number character varying(30),
    amount numeric(12,2),
    receipt_date date,
    uploaded_by uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    confirmed_at timestamptz,
    deleted_at timestamptz,
    deleted_by uuid,
    storage_purged_at timestamptz,
    CONSTRAINT transaction_receipts_pkey PRIMARY KEY (attachment_id)
  );`;

export class Cc045TransactionReceipts1794900200000 {
  name = 'Cc045TransactionReceipts1794900200000';

  async up(runner) {
    const [{ present }] = await runner.query("SELECT to_regclass('public.transaction_receipts') IS NOT NULL AS present");
    if (present) throw new Error('transaction_receipts already exists outside the migration history. Review it and write a fix-up migration.');
    await runner.query(TABLE_SQL);
    for (const [name, definition] of RECEIPT_CONSTRAINTS) await runner.query(`ALTER TABLE transaction_receipts ADD CONSTRAINT ${name} ${definition}`);
    for (const sql of RECEIPT_INDEXES) await runner.query(sql);
  }

  // Rows point at private objects: dropping them would orphan stored receipts. Empty the store first (or accept the loss with
  // a backup and CCMS_ALLOW_DATA_LOSS=<this migration>).
  async down(runner) {
    await assertTablesEmptyBeforeDrop(runner, this.name, ['transaction_receipts']);
    await runner.query('DROP TABLE IF EXISTS transaction_receipts');
  }
}
